use assert_cmd::Command;
use forge_core::artifact::hex_sha256;
use forge_core::storage::ForgeStore;
use rusqlite::Connection;
use serde_json::Value;
use std::fs;
#[cfg(unix)]
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use tempfile::tempdir;

/// Helper: create a workflow via ForgeStore and return its id.
fn setup_test_workflow(store: &ForgeStore) -> String {
    use forge_core::graph;
    use forge_core::intent;
    let workflow = graph::create_workflow(intent::parse_intent("Test workflow for patch apply"));
    store.save_workflow(&workflow).unwrap();
    workflow.id
}

fn forge() -> Command {
    Command::cargo_bin("forge").expect("forge binary should build")
}

fn sqlite_table_columns(connection: &Connection, table: &str) -> Vec<String> {
    let mut statement = connection
        .prepare(&format!("PRAGMA table_info({table})"))
        .unwrap();
    let rows = statement
        .query_map([], |row| row.get::<_, String>(1))
        .unwrap();
    rows.map(|row| row.unwrap()).collect()
}

fn sqlite_index_names(connection: &Connection, table: &str) -> Vec<String> {
    let mut statement = connection
        .prepare(&format!("PRAGMA index_list({table})"))
        .unwrap();
    let rows = statement
        .query_map([], |row| row.get::<_, String>(1))
        .unwrap();
    rows.map(|row| row.unwrap()).collect()
}

#[test]
fn harness_token_headroom_compresses_logs_and_mcp_wrap_plan_shapes_cli_environment() {
    let content = (0..80)
        .map(|index| format!("line {index}: error: failed to process request {index}"))
        .collect::<Vec<_>>()
        .join("\n");
    let output = forge()
        .args([
            "harness",
            "token-headroom",
            "--content",
            &content,
            "--kind",
            "log",
            "--budget-tokens",
            "120",
            "--source",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "forge.harness.token_headroom.v1");
    assert_eq!(json["content_kind"], "log");
    assert_eq!(json["strategy"], "signal_log_compressor");
    assert!(json["estimated_saved_tokens"].as_u64().unwrap() > 0);
    assert!(json["retrieval_ref"]
        .as_str()
        .unwrap()
        .starts_with("forge://harness/headroom/"));

    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let persisted_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "token-headroom",
            "--content",
            &content,
            "--kind",
            "log",
            "--budget-tokens",
            "120",
            "--source",
            "persisted-test",
            "--persist",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let persisted: Value = serde_json::from_slice(&persisted_output).unwrap();
    assert_eq!(persisted["persisted"], true);
    assert_eq!(persisted["retrieval_available"], true);
    assert_eq!(persisted["store_status"], "stored_local_sqlite");
    let retrieval_ref = persisted["retrieval_ref"].as_str().unwrap();
    let retrieval_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "retrieve-headroom",
            "--ref",
            retrieval_ref,
            "--include-content",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let retrieval: Value = serde_json::from_slice(&retrieval_output).unwrap();
    assert_eq!(
        retrieval["schema_version"],
        "forge.harness.headroom_retrieval.v1"
    );
    assert_eq!(retrieval["status"], "headroom_blob_retrieved");
    assert_eq!(retrieval["found"], true);
    assert_eq!(retrieval["source"], "persisted-test");
    assert_eq!(retrieval["original_content"], content);
    assert_eq!(
        retrieval["compressed_sha256"],
        persisted["compressed_sha256"]
    );

    let mcp_headroom_input = serde_json::json!({
        "content": "alpha\nbeta\nwarning: check this\nomega",
        "kind": "log",
        "budget_tokens": 12,
        "source": "mcp-persisted-test",
        "persist": true
    });
    let mcp_headroom_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.token_headroom",
            "--input",
            &mcp_headroom_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_headroom: Value = serde_json::from_slice(&mcp_headroom_output).unwrap();
    assert_eq!(mcp_headroom["result"]["persisted"], true);
    let mcp_retrieval_input = serde_json::json!({
        "retrieval_ref": mcp_headroom["result"]["retrieval_ref"],
        "include_content": true
    });
    let mcp_retrieval_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.retrieve_headroom",
            "--input",
            &mcp_retrieval_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_retrieval: Value = serde_json::from_slice(&mcp_retrieval_output).unwrap();
    assert_eq!(
        mcp_retrieval["result"]["schema_version"],
        "forge.harness.headroom_retrieval.v1"
    );
    assert_eq!(mcp_retrieval["result"]["found"], true);
    assert_eq!(mcp_retrieval["result"]["source"], "mcp-persisted-test");
    assert_eq!(
        mcp_retrieval["result"]["original_content"],
        "alpha\nbeta\nwarning: check this\nomega"
    );

    let mcp_input = serde_json::json!({
        "executor": "claude-code",
        "command": ["claude", "--model", "sonnet"],
        "forge_first": true,
        "workflow_id": "wf_demo",
        "task_id": "task_demo",
        "run_id": "run_demo",
        "context_budget": 2048,
        "token_headroom": true
    });
    let mcp_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.wrap_plan",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_json["schema_version"], "forge.mcp.call.v1");
    assert_eq!(
        mcp_json["result"]["schema_version"],
        "forge.harness.cli_wrapper_plan.v1"
    );
    assert_eq!(mcp_json["result"]["executor"], "claude");
    assert_eq!(mcp_json["result"]["forge_first"], true);
    assert!(mcp_json["result"]["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));
    let env = mcp_json["result"]["env"].as_array().unwrap();
    assert!(env
        .iter()
        .any(|item| item["name"] == "ENABLE_TOOL_SEARCH" && item["value"] == "true"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FORGE_WORKFLOW_ID" && item["value"] == "wf_demo"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FORGE_TASK_ID" && item["value"] == "task_demo"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FORGE_TOKEN_HEADROOM" && item["value"] == "enabled"));
    assert!(mcp_json["result"]["launch_command"]
        .as_array()
        .unwrap()
        .windows(2)
        .any(|pair| pair[0] == "--task" && pair[1] == "task_demo"));

    let exec_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--forge-first",
            "--workflow",
            "wf_demo",
            "--task",
            "task_demo",
            "--run",
            "run_demo",
            "--context-budget",
            "2048",
            "--",
            "definitely-not-a-real-forge-test-cli",
            "--version",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let exec_json: Value = serde_json::from_slice(&exec_output).unwrap();
    assert_eq!(exec_json["schema_version"], "forge.harness.exec_receipt.v1");
    assert_eq!(exec_json["status"], "harness_exec_dry_run");
    assert_eq!(exec_json["executor"], "codex");
    assert_eq!(exec_json["task_id"], "task_demo");
    assert_eq!(exec_json["dry_run"], true);
    assert_eq!(exec_json["allow_exec"], false);
    assert_eq!(exec_json["executed"], false);
    assert_eq!(exec_json["resolution_status"], "executable_missing");
    assert_eq!(
        exec_json["wrapper_plan"]["schema_version"],
        "forge.harness.cli_wrapper_plan.v1"
    );
    let exec_env = exec_json["wrapper_plan"]["env"].as_array().unwrap();
    assert!(exec_env
        .iter()
        .any(|item| item["name"] == "FORGE_RUN_ID" && item["value"] == "run_demo"));
    assert!(exec_env
        .iter()
        .any(|item| item["name"] == "FORGE_TASK_ID" && item["value"] == "task_demo"));

    let mcp_exec_input = serde_json::json!({
        "executor": "opencode",
        "command": ["definitely-not-a-real-forge-test-cli", "--help"],
        "forge_first": true,
        "workflow_id": "wf_demo",
        "task_id": "task_mcp_demo",
        "dry_run": true,
        "allow_exec": false
    });
    let mcp_exec_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.exec",
            "--input",
            &mcp_exec_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_exec: Value = serde_json::from_slice(&mcp_exec_output).unwrap();
    assert_eq!(
        mcp_exec["result"]["schema_version"],
        "forge.harness.exec_receipt.v1"
    );
    assert_eq!(mcp_exec["result"]["status"], "harness_exec_dry_run");
    assert_eq!(mcp_exec["result"]["executed"], false);
    assert_eq!(mcp_exec["result"]["task_id"], "task_mcp_demo");
    assert_eq!(mcp_exec["result"]["event_recorded"], true);
    assert!(mcp_exec["result"]["global_event_id"].as_i64().unwrap() > 0);
}

#[test]
fn harness_cli_honors_forge_first_default_mode_with_explicit_observe_only_override() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");

    let output = forge()
        .env("FORGE_HARNESS_DEFAULT_MODE", "forge_first")
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--workflow",
            "wf_default_harness",
            "--task",
            "task-default-harness",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "forge.harness.cli_wrapper_plan.v1");
    assert_eq!(json["forge_first"], true);
    assert_eq!(json["forge_first_source"], "env_default");
    assert!(json["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));
    let env = json["env"].as_array().unwrap();
    assert!(env
        .iter()
        .any(|item| item["name"] == "FORGE_HARNESS_MODE" && item["value"] == "forge_first"));
    assert!(env
        .iter()
        .any(|item| item["name"] == "FORGE_HARNESS_MODE_SOURCE" && item["value"] == "env_default"));

    let observe_only_output = forge()
        .env("FORGE_HARNESS_DEFAULT_MODE", "forge_first")
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--observe-only",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let observe_only: Value = serde_json::from_slice(&observe_only_output).unwrap();
    assert_eq!(observe_only["forge_first"], false);
    assert_eq!(observe_only["forge_first_source"], "observe_only_flag");
    assert!(!observe_only["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));

    let exec_output = forge()
        .env("FORGE_HARNESS_DEFAULT_MODE", "forge_first")
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "opencode",
            "--workflow",
            "wf_default_harness",
            "--task",
            "task-default-harness",
            "--",
            "definitely-not-a-real-forge-test-cli",
            "--version",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let exec_json: Value = serde_json::from_slice(&exec_output).unwrap();
    assert_eq!(exec_json["schema_version"], "forge.harness.exec_receipt.v1");
    assert_eq!(exec_json["forge_first"], true);
    assert_eq!(exec_json["forge_first_source"], "env_default");
    assert_eq!(exec_json["wrapper_plan"]["forge_first"], true);
    assert_eq!(
        exec_json["wrapper_plan"]["forge_first_source"],
        "env_default"
    );
    assert!(exec_json["wrapper_plan"]["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));
}

#[test]
fn harness_cli_honors_project_forge_first_default_mode_config() {
    let temp = tempdir().unwrap();
    let forge_dir = temp.path().join(".forge");
    fs::create_dir_all(&forge_dir).unwrap();
    fs::write(
        forge_dir.join("harness.json"),
        r#"{"default_mode":"forge_first"}"#,
    )
    .unwrap();

    let output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["forge_first"], true);
    assert_eq!(json["forge_first_source"], "project_config");
    assert!(json["env"]
        .as_array()
        .unwrap()
        .iter()
        .any(
            |item| item["name"] == "FORGE_HARNESS_MODE_SOURCE" && item["value"] == "project_config"
        ));
    assert!(json["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));

    let exec_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args([
            "harness",
            "exec",
            "--executor",
            "codex",
            "--",
            "definitely-not-a-real-forge-test-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let exec_json: Value = serde_json::from_slice(&exec_output).unwrap();
    assert_eq!(exec_json["forge_first"], true);
    assert_eq!(exec_json["forge_first_source"], "project_config");
    assert_eq!(
        exec_json["wrapper_plan"]["forge_first_source"],
        "project_config"
    );

    let observe_only_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--observe-only",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let observe_only: Value = serde_json::from_slice(&observe_only_output).unwrap();
    assert_eq!(observe_only["forge_first"], false);
    assert_eq!(observe_only["forge_first_source"], "observe_only_flag");
}

#[test]
fn harness_wrap_plan_can_use_explicit_project_root_default_mode_for_cli_and_mcp() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let project = temp.path().join("remote-project");
    let forge_dir = project.join(".forge");
    fs::create_dir_all(&forge_dir).unwrap();
    fs::write(
        forge_dir.join("harness.json"),
        r#"{"default_mode":"forge_first"}"#,
    )
    .unwrap();

    let cli_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .args([
            "harness",
            "wrap-plan",
            "--executor",
            "codex",
            "--cmd",
            "codex",
            "--project-root",
            project.to_str().unwrap(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let cli_plan: Value = serde_json::from_slice(&cli_output).unwrap();
    assert_eq!(cli_plan["forge_first"], true);
    assert_eq!(cli_plan["forge_first_source"], "project_config");
    assert!(cli_plan["launch_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("--forge-first".to_string())));

    let mcp_tools_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "tools",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_tools: Value = serde_json::from_slice(&mcp_tools_output).unwrap();
    let mcp_wrap_plan_tool = find_mcp_tool(&mcp_tools, "forge.harness.wrap_plan");
    assert_eq!(
        mcp_wrap_plan_tool["input_schema"]["properties"]["project_root"]["type"],
        "string"
    );

    let input = serde_json::json!({
        "executor": "codex",
        "command": ["codex"],
        "project_root": project.display().to_string()
    });
    let mcp_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.wrap_plan",
            "--input",
            &input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_plan: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_plan["result"]["forge_first"], true);
    assert_eq!(mcp_plan["result"]["forge_first_source"], "project_config");
}

#[test]
fn harness_mode_reports_effective_default_source_and_project_config_precedence() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args(["harness", "mode", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let default_mode: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(default_mode["schema_version"], "forge.harness.mode.v1");
    assert_eq!(default_mode["status"], "harness_mode_resolved");
    assert_eq!(default_mode["forge_first"], false);
    assert_eq!(default_mode["effective_mode"], "observe_only");
    assert_eq!(default_mode["forge_first_source"], "default_observe_only");
    assert_eq!(default_mode["env_default_present"], false);
    assert_eq!(default_mode["project_config_status"], "missing");
    assert_eq!(default_mode["project_exec_policy_status"], "missing");
    assert_eq!(default_mode["require_lineage_for_exec"], false);
    assert!(default_mode["project_config_path"]
        .as_str()
        .unwrap()
        .ends_with(".forge/harness.json"));
    assert!(default_mode["project_exec_policy_path"]
        .as_str()
        .unwrap()
        .ends_with(".forge/harness.json"));
    assert_eq!(
        default_mode["precedence"],
        serde_json::json!([
            "observe_only_flag",
            "explicit_flag",
            "env_default",
            "project_config",
            "default_observe_only"
        ])
    );

    let forge_dir = temp.path().join(".forge");
    fs::create_dir_all(&forge_dir).unwrap();
    fs::write(
        forge_dir.join("harness.json"),
        r#"{"default_mode":"forge_first","require_lineage_for_exec":true}"#,
    )
    .unwrap();
    let project_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args(["harness", "mode", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let project_mode: Value = serde_json::from_slice(&project_output).unwrap();
    assert_eq!(project_mode["forge_first"], true);
    assert_eq!(project_mode["effective_mode"], "forge_first");
    assert_eq!(project_mode["forge_first_source"], "project_config");
    assert_eq!(project_mode["project_config_status"], "loaded");
    assert_eq!(project_mode["project_default_mode"], "forge_first");
    assert_eq!(
        project_mode["project_exec_policy_status"],
        "lineage_required_missing"
    );
    assert_eq!(project_mode["require_lineage_for_exec"], true);
    assert!(project_mode["safety_checks"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("project_require_lineage_for_exec")));

    let mcp_tools_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "tools",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_tools: Value = serde_json::from_slice(&mcp_tools_output).unwrap();
    let mcp_mode_tool = find_mcp_tool(&mcp_tools, "forge.harness.mode");
    assert_eq!(mcp_mode_tool["output_schema"], "forge.harness.mode.v1");
    assert_eq!(
        mcp_mode_tool["input_schema"]["properties"]["observe_only"]["type"],
        "boolean"
    );
    assert_eq!(mcp_mode_tool["async_safe"], true);
    assert_eq!(mcp_mode_tool["mutates_workflow"], false);

    let mcp_mode_output = forge()
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.mode",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_mode: Value = serde_json::from_slice(&mcp_mode_output).unwrap();
    assert_eq!(mcp_mode["schema_version"], "forge.mcp.call.v1");
    assert_eq!(
        mcp_mode["result"]["schema_version"],
        "forge.harness.mode.v1"
    );
    assert_eq!(mcp_mode["result"]["forge_first"], true);
    assert_eq!(mcp_mode["result"]["forge_first_source"], "project_config");
    assert_eq!(mcp_mode["result"]["project_config_status"], "loaded");
    assert_eq!(
        mcp_mode["result"]["project_exec_policy_status"],
        "lineage_required_missing"
    );
    assert_eq!(mcp_mode["result"]["require_lineage_for_exec"], true);

    let env_output = forge()
        .env("FORGE_HARNESS_DEFAULT_MODE", "forge_first")
        .current_dir(temp.path())
        .args(["harness", "mode", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let env_mode: Value = serde_json::from_slice(&env_output).unwrap();
    assert_eq!(env_mode["forge_first"], true);
    assert_eq!(env_mode["forge_first_source"], "env_default");
    assert_eq!(env_mode["env_default_present"], true);
    assert_eq!(env_mode["env_default_value"], "forge_first");
    assert_eq!(env_mode["project_config_status"], "loaded");

    let observe_output = forge()
        .env("FORGE_HARNESS_DEFAULT_MODE", "forge_first")
        .current_dir(temp.path())
        .args(["harness", "mode", "--observe-only", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let observe_mode: Value = serde_json::from_slice(&observe_output).unwrap();
    assert_eq!(observe_mode["forge_first"], false);
    assert_eq!(observe_mode["effective_mode"], "observe_only");
    assert_eq!(observe_mode["forge_first_source"], "observe_only_flag");
}

#[cfg(unix)]
#[test]
fn harness_exec_applies_headroom_to_child_output_and_persists_retrieval_refs() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let bin_dir = temp.path().join("bin");
    fs::create_dir_all(&bin_dir).unwrap();
    write_fake_executor(
        &bin_dir,
        "forge-noisy-cli",
        r#"#!/bin/sh
for i in $(seq 1 80); do
  printf 'line %s: error: failed to process request %s\n' "$i" "$i"
done
"#,
    );
    let path = format!(
        "{}:{}",
        bin_dir.display(),
        std::env::var("PATH").unwrap_or_default()
    );

    let output = forge()
        .env("PATH", path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--forge-first",
            "--workflow",
            "wf_noisy",
            "--task",
            "task-noisy",
            "--run",
            "run_noisy",
            "--context-budget",
            "120",
            "--execute",
            "--allow-exec",
            "--output",
            "json",
            "--",
            "forge-noisy-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let receipt: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(receipt["schema_version"], "forge.harness.exec_receipt.v1");
    assert_eq!(receipt["status"], "harness_exec_completed");
    assert_eq!(receipt["task_id"], "task-noisy");
    assert_eq!(receipt["executed"], true);
    assert_eq!(receipt["event_recorded"], true);
    assert!(receipt["global_event_id"].as_i64().unwrap() > 0);
    assert_eq!(receipt["output_headroom_enabled"], true);
    assert_eq!(
        receipt["stdout_headroom"]["schema_version"],
        "forge.harness.token_headroom.v1"
    );
    assert_eq!(receipt["stdout_headroom"]["content_kind"], "log");
    assert_eq!(
        receipt["stdout_headroom"]["strategy"],
        "signal_log_compressor"
    );
    assert_eq!(receipt["stdout_headroom"]["persisted"], true);
    assert_eq!(
        receipt["stdout_headroom"]["store_status"],
        "stored_local_sqlite"
    );
    assert_eq!(receipt["stdout_headroom"]["budget_tokens"], 120);
    assert!(
        receipt["stdout_headroom"]["estimated_saved_tokens"]
            .as_u64()
            .unwrap()
            > 0
    );
    assert!(receipt["stdout_headroom"]["retrieval_ref"]
        .as_str()
        .unwrap()
        .starts_with("forge://harness/headroom/"));

    let retrieval_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "retrieve-headroom",
            "--ref",
            receipt["stdout_headroom"]["retrieval_ref"]
                .as_str()
                .unwrap(),
            "--include-content",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let retrieval: Value = serde_json::from_slice(&retrieval_output).unwrap();
    assert_eq!(retrieval["status"], "headroom_blob_retrieved");
    assert_eq!(retrieval["source"], "harness-exec:codex:stdout");
    assert!(retrieval["original_content"]
        .as_str()
        .unwrap()
        .contains("line 80: error: failed to process request 80"));

    let timeline_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "events",
            "timeline",
            "--workflow",
            "wf_noisy",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let timeline: Value = serde_json::from_slice(&timeline_output).unwrap();
    let harness_event = timeline["events"]
        .as_array()
        .unwrap()
        .iter()
        .find(|event| event["kind"] == "harness_exec_completed")
        .unwrap();
    assert_eq!(harness_event["source"], "forge_harness");
    assert_eq!(harness_event["data"]["status"], "completed");
    assert_eq!(harness_event["data"]["global_event"]["status"], "completed");
    assert_eq!(harness_event["correlation"]["run_id"], "run_noisy");
    assert_eq!(harness_event["correlation"]["task_id"], "task-noisy");
    assert_eq!(
        harness_event["data"]["receipt"]["schema_version"],
        "forge.harness.exec_receipt.v1"
    );
    assert_eq!(
        harness_event["data"]["receipt"]["stdout_headroom"]["retrieval_ref"],
        receipt["stdout_headroom"]["retrieval_ref"]
    );
}

#[test]
fn harness_exec_enforces_project_lineage_policy_before_real_brain_execution() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let forge_dir = temp.path().join(".forge");
    let bin_dir = temp.path().join("bin");
    fs::create_dir_all(&forge_dir).unwrap();
    fs::create_dir_all(&bin_dir).unwrap();
    fs::write(
        forge_dir.join("harness.json"),
        r#"{"default_mode":"forge_first","require_lineage_for_exec":true}"#,
    )
    .unwrap();
    write_fake_executor(
        &bin_dir,
        "forge-policy-cli",
        r#"#!/bin/sh
printf 'policy-exec-ok:%s\n' "$FORGE_WORKFLOW_ID"
"#,
    );
    let path = format!(
        "{}:{}",
        bin_dir.display(),
        std::env::var("PATH").unwrap_or_default()
    );

    let blocked = forge()
        .env("PATH", &path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--execute",
            "--allow-exec",
            "--cwd",
            temp.path().to_str().unwrap(),
            "--output",
            "json",
            "--",
            "forge-policy-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let blocked_json: Value = serde_json::from_slice(&blocked).unwrap();
    assert_eq!(
        blocked_json["status"],
        "harness_exec_blocked_by_project_policy"
    );
    assert_eq!(blocked_json["executed"], false);
    assert_eq!(
        blocked_json["project_policy_status"],
        "lineage_required_missing"
    );
    assert_eq!(blocked_json["require_lineage_for_exec"], true);
    assert!(blocked_json["safety_checks"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("project_require_lineage_for_exec")));
    assert!(blocked_json["notes"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!(
            "Project harness policy requires workflow, task and run lineage before real execution."
        )));

    let allowed = forge()
        .env("PATH", &path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--forge-first",
            "--workflow",
            "wf_policy",
            "--task",
            "task-policy",
            "--run",
            "run-policy",
            "--execute",
            "--allow-exec",
            "--cwd",
            temp.path().to_str().unwrap(),
            "--output",
            "json",
            "--",
            "forge-policy-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let allowed_json: Value = serde_json::from_slice(&allowed).unwrap();
    assert_eq!(allowed_json["status"], "harness_exec_completed");
    assert_eq!(allowed_json["executed"], true);
    assert_eq!(
        allowed_json["project_policy_status"],
        "lineage_required_satisfied"
    );
    assert_eq!(allowed_json["event_recorded"], true);
    assert!(allowed_json["stdout_excerpt"]
        .as_str()
        .unwrap()
        .contains("policy-exec-ok:wf_policy"));

    let mcp_input = serde_json::json!({
        "executor": "codex",
        "command": ["forge-policy-cli"],
        "dry_run": false,
        "allow_exec": true,
        "cwd": temp.path().display().to_string()
    });
    let mcp_blocked = forge()
        .env("PATH", &path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.exec",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_blocked).unwrap();
    assert_eq!(
        mcp_json["result"]["status"],
        "harness_exec_blocked_by_project_policy"
    );
    assert_eq!(mcp_json["result"]["executed"], false);
    assert_eq!(
        mcp_json["result"]["project_policy_status"],
        "lineage_required_missing"
    );
}

#[test]
fn harness_exec_can_use_explicit_project_root_without_changing_child_cwd_for_cli_and_mcp() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let project = temp.path().join("remote-project");
    let child_cwd = temp.path().join("child-cwd");
    let bin_dir = temp.path().join("bin");
    fs::create_dir_all(project.join(".forge")).unwrap();
    fs::create_dir_all(&child_cwd).unwrap();
    fs::create_dir_all(&bin_dir).unwrap();
    fs::write(
        project.join(".forge").join("harness.json"),
        r#"{"default_mode":"forge_first","require_lineage_for_exec":true}"#,
    )
    .unwrap();
    write_fake_executor(
        &bin_dir,
        "forge-project-root-cli",
        r#"#!/bin/sh
printf 'pwd:%s workflow:%s source:%s\n' "$PWD" "$FORGE_WORKFLOW_ID" "$FORGE_HARNESS_MODE_SOURCE"
"#,
    );
    let path = format!(
        "{}:{}",
        bin_dir.display(),
        std::env::var("PATH").unwrap_or_default()
    );

    let blocked = forge()
        .env("PATH", &path)
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--project-root",
            project.to_str().unwrap(),
            "--execute",
            "--allow-exec",
            "--cwd",
            child_cwd.to_str().unwrap(),
            "--output",
            "json",
            "--",
            "forge-project-root-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let blocked_json: Value = serde_json::from_slice(&blocked).unwrap();
    assert_eq!(
        blocked_json["status"],
        "harness_exec_blocked_by_project_policy"
    );
    assert_eq!(blocked_json["forge_first"], true);
    assert_eq!(blocked_json["forge_first_source"], "project_config");
    assert_eq!(blocked_json["cwd"], child_cwd.display().to_string());
    assert_eq!(
        blocked_json["project_policy_path"],
        project
            .join(".forge")
            .join("harness.json")
            .display()
            .to_string()
    );
    assert_eq!(
        blocked_json["project_policy_status"],
        "lineage_required_missing"
    );

    let allowed = forge()
        .env("PATH", &path)
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .args([
            "--store",
            store.to_str().unwrap(),
            "harness",
            "exec",
            "--executor",
            "codex",
            "--project-root",
            project.to_str().unwrap(),
            "--workflow",
            "wf_project_root",
            "--task",
            "task-project-root",
            "--run",
            "run-project-root",
            "--execute",
            "--allow-exec",
            "--cwd",
            child_cwd.to_str().unwrap(),
            "--output",
            "json",
            "--",
            "forge-project-root-cli",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let allowed_json: Value = serde_json::from_slice(&allowed).unwrap();
    assert_eq!(allowed_json["status"], "harness_exec_completed");
    assert_eq!(allowed_json["forge_first_source"], "project_config");
    assert_eq!(
        allowed_json["project_policy_status"],
        "lineage_required_satisfied"
    );
    let stdout_excerpt = allowed_json["stdout_excerpt"].as_str().unwrap();
    assert!(stdout_excerpt.contains(&format!("pwd:{}", child_cwd.display())));
    assert!(stdout_excerpt.contains("workflow:wf_project_root"));
    assert!(stdout_excerpt.contains("source:project_config"));

    let mcp_tools_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "tools",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_tools: Value = serde_json::from_slice(&mcp_tools_output).unwrap();
    let mcp_exec_tool = find_mcp_tool(&mcp_tools, "forge.harness.exec");
    assert_eq!(
        mcp_exec_tool["input_schema"]["properties"]["project_root"]["type"],
        "string"
    );

    let mcp_input = serde_json::json!({
        "executor": "codex",
        "command": ["forge-project-root-cli"],
        "project_root": project.display().to_string(),
        "workflow_id": "wf_mcp_project_root",
        "task_id": "task-mcp-project-root",
        "run_id": "run-mcp-project-root",
        "dry_run": false,
        "allow_exec": true,
        "cwd": child_cwd.display().to_string()
    });
    let mcp_output = forge()
        .env("PATH", &path)
        .env_remove("FORGE_HARNESS_DEFAULT_MODE")
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "call",
            "forge.harness.exec",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_json["result"]["status"], "harness_exec_completed");
    assert_eq!(mcp_json["result"]["forge_first_source"], "project_config");
    assert_eq!(mcp_json["result"]["cwd"], child_cwd.display().to_string());
    assert!(mcp_json["result"]["stdout_excerpt"]
        .as_str()
        .unwrap()
        .contains("source:project_config"));
}

