#[test]
fn milestone_manifest_surfaces_requirements_evidence_gaps_and_promotion_decision() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");

    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "milestone",
            "manifest",
            "--version",
            "0.5",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "forge.milestone.manifest.v1");
    assert_eq!(json["milestone"], "0.5");
    assert!(json["release_line_boundary"]
        .as_str()
        .unwrap()
        .contains("0.4.x"));
    assert!(json["requirements"].as_array().unwrap().len() >= 11);
    assert!(json["completed_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(
            |capability| capability["id"] == "scheduler_loop_subflow_foundation"
                && capability["promotion_ready"] == true
        ));
    assert!(json["completed_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "export_demo_baseline"
            && capability["promotion_ready"] == true));
    assert!(json["completed_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(
            |capability| capability["id"] == "research_artifact_baseline"
                && capability["promotion_ready"] == true
        ));
    assert!(json["validation_evidence"]
        .as_array()
        .unwrap()
        .iter()
        .any(|evidence| evidence["capability_id"] == "creative_artifact_ir"));
    assert!(json["demos"]
        .as_array()
        .unwrap()
        .iter()
        .any(|demo| demo["capability_id"] == "export_demo_baseline"));
    assert!(json["known_gaps"]
        .as_array()
        .unwrap()
        .iter()
        .all(|gap| gap["capability_id"] != "live_collaboration"));
    assert!(json["missing_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(|capability| capability["id"] == "replacement_grade_cli"
            && capability["promotion_ready"] == false));
    assert!(json["missing_capabilities"]
        .as_array()
        .unwrap()
        .iter()
        .any(
            |capability| capability["id"] == "experimental_multimodal_runtime"
                && capability["promotion_ready"] == false
        ));
    assert_eq!(json["promotion_decision"]["decision"], "fail");
    assert_eq!(json["promotion_decision"]["promotable"], false);
    assert!(
        json["promotion_decision"]["blocked_by"]
            .as_array()
            .unwrap()
            .contains(&serde_json::json!("replacement_grade_cli")),
        "replacement-grade CLI is new 0.5 scope and must block promotion until it has demo evidence"
    );
}

#[test]
fn milestone_boundary_document_matches_validated_export_demo_runtime_state() {
    let docs = fs::read_to_string("docs/forge-0.5-milestone.md").unwrap();

    assert!(
        docs.contains("| Export/demo baseline | validated |"),
        "the visible 0.5 milestone boundary must match the runtime manifest after export-demo validation"
    );
    assert!(
        docs.contains("forge milestone export-demo"),
        "the milestone boundary should expose the native export-demo command as validation evidence"
    );
    assert!(
        docs.contains("promotion decision"),
        "the milestone boundary should explain that promotion is a gated runtime decision"
    );
    assert!(
        docs.contains("| Replacement-grade Forge CLI | groundwork |"),
        "the visible 0.5 milestone boundary must include the new replacement-grade CLI scope"
    );
    assert!(
        docs.contains("| Experimental multimodal runtime | groundwork |"),
        "the visible 0.5 milestone boundary must include the new disabled-by-default multimodal scope"
    );
    assert!(
        docs.contains("forge multimodal benchmark-template"),
        "the visible 0.5 milestone boundary should point to benchmark-template evidence"
    );
    assert!(
        docs.contains("forge multimodal demo-plan"),
        "the visible 0.5 milestone boundary should point to guarded demo-plan evidence"
    );
    assert!(
        docs.contains("forge multimodal benchmark-result"),
        "the visible 0.5 milestone boundary should point to approved fixture-only benchmark result evidence"
    );
    assert!(
        docs.contains("forge.multimodal.benchmark_result"),
        "the visible 0.5 milestone boundary should expose the MCP benchmark result surface"
    );
    assert!(
        docs.contains(".forge/multimodal.json"),
        "the visible 0.5 milestone boundary should point to explicit multimodal feature-flag config"
    );
    assert!(
        docs.contains("forge milestone cli-demo"),
        "the visible 0.5 milestone boundary should point to replacement-grade CLI demo evidence"
    );
    assert!(
        docs.contains("forge.milestone.cli_demo"),
        "the visible 0.5 milestone boundary should expose the MCP CLI demo surface"
    );
}

