#[test]
fn patch_review_summarizes_current_diff_without_applying_changes() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let target = temp.path().join("sample.txt");
    fs::write(&target, "alpha\n").unwrap();
    let git_init = std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run");
    assert!(git_init.success());
    let git_add = std::process::Command::new("git")
        .args(["add", "sample.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run");
    assert!(git_add.success());

    let planned = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate a Forge-owned file patch review",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let planned_json: Value = serde_json::from_slice(&planned).unwrap();
    let workflow_id = planned_json["workflow_id"].as_str().unwrap();

    forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "plan",
            "--workflow",
            workflow_id,
            "--task",
            "task-001",
            "--intent",
            "Review the sample file diff",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success();

    fs::write(&target, "alpha\nbeta\n").unwrap();
    let before_review = fs::read(&target).unwrap();

    let output = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "review",
            "--workflow",
            workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let after_review = fs::read(&target).unwrap();
    assert_eq!(
        before_review, after_review,
        "patch review must not edit source files"
    );

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "forge.patch_review.v1");
    assert_eq!(json["status"], "patch_review_ready");
    assert_eq!(json["workflow_id"], workflow_id);
    assert_eq!(json["task_id"], "task-001");
    assert_eq!(json["applies_changes"], false);
    assert_eq!(json["external_resources_mutated"], false);
    assert_eq!(json["requires_human_approval"], true);
    assert_eq!(json["summary"]["changed_path_count"], 1);
    assert_eq!(json["summary"]["diff_present"], true);
    assert_eq!(json["summary"]["diff_check_passed"], true);
    assert_eq!(
        json["summary"]["approval_recommendation"],
        "ready_for_human_review"
    );
    assert!(json["path_reviews"]
        .as_array()
        .unwrap()
        .iter()
        .any(|review| review["path"] == "sample.txt"
            && review["changed"] == true
            && review["diff_excerpt"].as_str().unwrap().contains("+beta")));
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_review-"));
}

#[test]
fn patch_diff_builds_multi_file_navigation_without_applying_changes() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let first = temp.path().join("sample.txt");
    let second = temp.path().join("notes.txt");
    fs::write(&first, "alpha\nbravo\ncharlie\n").unwrap();
    fs::write(&second, "one\ntwo\nthree\n").unwrap();
    assert!(std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run")
        .success());
    assert!(std::process::Command::new("git")
        .args(["add", "sample.txt", "notes.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run")
        .success());
    assert!(std::process::Command::new("git")
        .args([
            "-c",
            "user.email=test@example.com",
            "-c",
            "user.name=Forge Test",
            "commit",
            "-m",
            "initial",
        ])
        .current_dir(temp.path())
        .status()
        .expect("git commit should run")
        .success());

    let planned = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate multi-file diff navigation",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let workflow_id = serde_json::from_slice::<Value>(&planned).unwrap()["workflow_id"]
        .as_str()
        .unwrap()
        .to_string();

    fs::write(&first, "alpha\nbravo changed\ncharlie\n").unwrap();
    fs::write(&second, "one\ntwo changed\nthree\n").unwrap();

    let output = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "diff",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--path",
            "notes.txt",
            "--file-index",
            "1",
            "--hunk-index",
            "0",
            "--context-lines",
            "2",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    assert_eq!(
        fs::read_to_string(&first).unwrap(),
        "alpha\nbravo changed\ncharlie\n"
    );
    assert_eq!(
        fs::read_to_string(&second).unwrap(),
        "one\ntwo changed\nthree\n"
    );
    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["schema_version"], "forge.patch_diff.v1");
    assert_eq!(json["status"], "patch_diff_ready");
    assert_eq!(json["applies_changes"], false);
    assert_eq!(json["external_resources_mutated"], false);
    assert_eq!(json["summary"]["changed_file_count"], 2);
    assert_eq!(json["selection"]["selected_file_index"], 1);
    assert_eq!(json["selection"]["selected_hunk_index"], 0);
    assert_eq!(json["selection"]["selected_path"], "notes.txt");
    assert_eq!(json["navigation"]["has_previous_file"], true);
    assert_eq!(json["navigation"]["has_next_file"], false);
    assert!(json["files"].as_array().unwrap().len() >= 2);
    assert!(json["files"][0]["hunks"].as_array().unwrap().len() >= 1);
    assert!(json["files"][1]["hunks"][0]["lines"]
        .as_array()
        .unwrap()
        .iter()
        .any(|line| line["kind"] == "addition" && line["content"] == "two changed"));
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_diff-"));
}

