fn patch_apply_records_file_state_and_validation() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let workflow_id = setup_test_workflow(&store);

    // Use empty validation commands to avoid recursive test execution.
    let report = forge_core::patch::build_patch_apply(
        &store,
        &workflow_id,
        "task-001",
        vec!["Cargo.toml".to_string()],
        "test",
        None,
        Some(&[]),
    )
    .unwrap();

    assert_eq!(report.schema_version, "forge.patch_apply.v1");
    assert_eq!(report.status, "patch_applied");
    assert_eq!(report.workflow_id, workflow_id);
    assert_eq!(report.task_id, "task-001");
    assert!(report
        .file_snapshots
        .iter()
        .any(|s| s.path == "Cargo.toml" && s.exists));
    assert!(report.validation.passed);
    assert!(!report.rollback_instructions.is_empty());
    assert!(report.artifact.is_some());
    assert!(report
        .artifact
        .as_ref()
        .unwrap()
        .path
        .contains("attached-patch_apply-"));
}

#[test]
fn patch_revert_records_proposal_without_restoring_files_automatically() {
    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let workflow_id = setup_test_workflow(&store);

    // Read original Cargo.toml content to verify revert restores it.
    let original_content = fs::read("Cargo.toml").unwrap();
    let original_sha256 = hex_sha256(&original_content);

    // Apply with no validation commands (fast in test context).
    let apply_report = forge_core::patch::build_patch_apply(
        &store,
        &workflow_id,
        "task-001",
        vec!["Cargo.toml".to_string()],
        "test",
        None,
        Some(&[]),
    )
    .unwrap();

    assert_eq!(apply_report.status, "patch_applied");
    // The artifact path is relative to base_dir – resolve it to an absolute path.
    let apply_artifact_path = store
        .base_dir()
        .join(&apply_report.artifact.as_ref().unwrap().path);
    let apply_artifact_str = apply_artifact_path.to_str().unwrap().to_string();

    // Revert records a guarded rollback proposal by default; Forge must not
    // run a destructive git checkout without an explicit human approval path.
    let revert_report = forge_core::patch::build_patch_revert(
        &store,
        &workflow_id,
        "task-001",
        &apply_artifact_str,
        "test",
        Some(&[]),
    )
    .unwrap();

    assert_eq!(revert_report.schema_version, "forge.patch_revert.v1");
    assert_eq!(revert_report.status, "patch_revert_proposed");
    assert_eq!(revert_report.workflow_id, workflow_id);
    assert_eq!(revert_report.task_id, "task-001");
    assert!(!revert_report.restore_executed);
    assert!(revert_report.requires_human_approval);
    assert!(revert_report
        .approval_command
        .as_ref()
        .unwrap()
        .contains("git checkout -- Cargo.toml"));
    assert!(revert_report.restored_snapshots.is_empty());
    assert!(revert_report.validation.commands.is_empty());
    assert!(revert_report.artifact.is_some());
    assert!(revert_report
        .artifact
        .as_ref()
        .unwrap()
        .path
        .contains("attached-patch_revert-"));

    // Verify file content is unchanged after round trip.
    let after_content = fs::read("Cargo.toml").unwrap();
    let after_sha256 = hex_sha256(&after_content);
    assert_eq!(
        original_sha256, after_sha256,
        "revert must restore original file content"
    );
}

#[test]
fn patch_restore_executes_git_restore_only_with_explicit_approval() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let target = temp.path().join("sample.txt");
    fs::write(&target, "alpha\n").unwrap();
    assert!(std::process::Command::new("git")
        .arg("init")
        .current_dir(temp.path())
        .status()
        .expect("git init should run")
        .success());
    assert!(std::process::Command::new("git")
        .args(["add", "sample.txt"])
        .current_dir(temp.path())
        .status()
        .expect("git add should run")
        .success());
    assert!(std::process::Command::new("git")
        .args([
            "-c",
            "user.email=test@example.com",
            "-c",
            "user.name=Forge Test",
            "commit",
            "-m",
            "initial",
        ])
        .current_dir(temp.path())
        .status()
        .expect("git commit should run")
        .success());

    let planned = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Demonstrate approved patch restore",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let workflow_id = serde_json::from_slice::<Value>(&planned).unwrap()["workflow_id"]
        .as_str()
        .unwrap()
        .to_string();

    fs::write(&target, "alpha\nbeta\n").unwrap();

    let apply_output = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "apply",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--path",
            "sample.txt",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let apply_json: Value = serde_json::from_slice(&apply_output).unwrap();
    let apply_artifact = apply_json["artifact"]["path"].as_str().unwrap();
    let apply_artifact_path = if Path::new(apply_artifact).is_absolute() {
        apply_artifact.to_string()
    } else {
        temp.path()
            .join(apply_artifact)
            .to_string_lossy()
            .to_string()
    };

    let revert_output = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "revert",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--apply-artifact",
            &apply_artifact_path,
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let revert_json: Value = serde_json::from_slice(&revert_output).unwrap();
    let revert_artifact = revert_json["artifact"]["path"].as_str().unwrap();
    let revert_artifact_path = if Path::new(revert_artifact).is_absolute() {
        revert_artifact.to_string()
    } else {
        temp.path()
            .join(revert_artifact)
            .to_string_lossy()
            .to_string()
    };

    forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "restore",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--revert-artifact",
            &revert_artifact_path,
            "--approved-by",
            "tester",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .stderr(predicates::str::contains("--confirm-restore"));
    assert_eq!(fs::read_to_string(&target).unwrap(), "alpha\nbeta\n");

    let restore_output = forge()
        .current_dir(temp.path())
        .args([
            "--store",
            store.to_str().unwrap(),
            "patch",
            "restore",
            "--workflow",
            &workflow_id,
            "--task",
            "task-001",
            "--revert-artifact",
            &revert_artifact_path,
            "--approved-by",
            "tester",
            "--confirm-restore",
            "--origin",
            "test",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    assert_eq!(fs::read_to_string(&target).unwrap(), "alpha\n");
    let json: Value = serde_json::from_slice(&restore_output).unwrap();
    assert_eq!(json["schema_version"], "forge.patch_restore.v1");
    assert_eq!(json["status"], "patch_restored");
    assert_eq!(json["workflow_id"], workflow_id);
    assert_eq!(json["task_id"], "task-001");
    assert_eq!(json["restore_executed"], true);
    assert_eq!(json["requires_human_approval"], true);
    assert_eq!(json["approved_by"], "tester");
    assert!(json["restored_paths"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("sample.txt")));
    assert_eq!(json["restore_command"]["status"], "passed");
    assert!(json["artifact"]["path"]
        .as_str()
        .unwrap()
        .contains("attached-patch_restore-"));
}

