#[test]
fn mcp_exposes_patch_apply_and_revert_tools() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");

    assert!(
        forge_core::skill::SKILL_MD.contains("forge patch apply"),
        "the packaged Forge skill should teach agents to record bounded patch apply artifacts"
    );
    assert!(
        forge_core::skill::SKILL_MD.contains("forge patch revert"),
        "the packaged Forge skill should teach agents to request guarded patch revert proposals"
    );
    assert!(
        forge_core::skill::SKILL_MD.contains("forge.patch.apply"),
        "the packaged Forge skill should expose the MCP patch apply tool"
    );
    assert!(
        forge_core::skill::SKILL_MD.contains("forge.patch.revert"),
        "the packaged Forge skill should expose the MCP patch revert tool"
    );

    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "mcp",
            "tools",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let tools = json["tools"].as_array().unwrap();

    let apply_tool = tools.iter().find(|t| t["name"] == "forge.patch.apply");
    assert!(
        apply_tool.is_some(),
        "forge.patch.apply tool must be in MCP manifest"
    );
    if let Some(tool) = apply_tool {
        assert_eq!(tool["output_schema"], "forge.patch_apply.v1");
        let required: Vec<&str> = tool["input_schema"]["required"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert!(required.contains(&"workflow_id"));
        assert!(required.contains(&"task_id"));
        assert!(required.contains(&"paths"));
    }

    let revert_tool = tools.iter().find(|t| t["name"] == "forge.patch.revert");
    assert!(
        revert_tool.is_some(),
        "forge.patch.revert tool must be in MCP manifest"
    );
    if let Some(tool) = revert_tool {
        assert_eq!(tool["output_schema"], "forge.patch_revert.v1");
        let required: Vec<&str> = tool["input_schema"]["required"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert!(required.contains(&"workflow_id"));
        assert!(required.contains(&"task_id"));
        assert!(required.contains(&"apply_artifact"));
    }
}

