#[test]
fn improve_benchmark_event_policy_validates_equivalence_before_promotion() {
    use forge_core::graph::{self, ExecutorKind, TaskStatus};
    use forge_core::intent;

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(intent::parse_intent(
        "Benchmark an applied event policy before promotion",
    ));
    workflow.tasks = vec![graph::task(
        "task-policy",
        "Render repeatable partner report",
        &[],
        &[],
        vec![],
        "same partner report output",
        (ExecutorKind::Ai, 2.0),
    )];
    workflow.tasks[0].status = TaskStatus::Completed;
    workflow.tasks[0]
        .work_item
        .goal_validation
        .definitively_ready = true;
    store.save_workflow(&workflow).unwrap();
    {
        let connection = Connection::open(&store_path).unwrap();
        for index in 0..3 {
            let source_id = format!("event-policy-benchmark-{index}");
            let created_at = format!("2026-06-10T13:{:02}:00Z", index * 5);
            let data = serde_json::json!({
                "node_id": "task-policy",
                "addon_id": "forge.addon.reporting",
                "duration_ms": 700,
                "retry_count": 0,
                "wait_seconds": 5,
                "context": {
                    "effective_budget": 1000,
                    "routing_summary": {
                        "selected_bytes": 900 + index,
                        "remaining_budget": 100 - index
                    },
                    "memory_policy": {
                        "memory_level": "standard",
                        "memory_scope": "project"
                    }
                }
            });
            connection
                .execute(
                    r#"
                    INSERT INTO global_events (
                        source, source_id, workflow_id, kind, origin, status,
                        organization_id, brand_id, product_id, user_id, channel_id,
                        tenant_context_json, data_json, created_at
                    )
                    VALUES (
                        'event_policy_benchmark_seed', ?1, ?2, 'ai_executor_completed', 'codex', 'recorded',
                        'org-demo', 'brand-demo', 'product-demo', 'user-demo', 'web',
                        '{}', ?3, ?4
                    )
                    "#,
                    rusqlite::params![source_id, workflow.id, data.to_string(), created_at],
                )
                .unwrap();
        }
    }

    forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "apply-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--apply",
            "--approved-by",
            "codex-test",
            "--output",
            "json",
        ])
        .assert()
        .success();

    let benchmark_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "benchmark-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let benchmark: Value = serde_json::from_slice(&benchmark_output).unwrap();
    assert_eq!(
        benchmark["schema_version"],
        "forge.improve.event_policy_benchmark.v1"
    );
    assert_eq!(benchmark["status"], "event_policy_benchmark_validated");
    assert_eq!(benchmark["workflow_id"], workflow.id);
    assert_eq!(benchmark["recommended_policy"], "prefer_deterministic_node");
    assert_eq!(benchmark["equivalence"]["status"], "equivalent");
    assert_eq!(benchmark["equivalence"]["promotion_allowed"], true);
    assert_eq!(benchmark["benchmark"]["validation_passed"], true);
    assert_eq!(benchmark["benchmark"]["rollback_ready"], true);
    assert_eq!(benchmark["promotion_decision"]["status"], "promotion_ready");
    assert_eq!(benchmark["promotion_decision"]["auto_promoted"], false);
    assert_eq!(
        benchmark["event_kind"],
        "event_improvement_policy_benchmarked"
    );

    let mcp_input = serde_json::json!({
        "workflow_id": workflow.id,
        "recommended_policy": "prefer_deterministic_node",
        "origin": "mcp-test"
    });
    let mcp_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "mcp",
            "call",
            "forge.improve.benchmark_event_policy",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(
        mcp_json["result"]["schema_version"],
        "forge.improve.event_policy_benchmark.v1"
    );
    assert_eq!(
        mcp_json["result"]["promotion_decision"]["auto_promoted"],
        false
    );

    let updated = ForgeStore::open(&store_path)
        .unwrap()
        .load_workflow(&workflow.id)
        .unwrap();
    assert_eq!(
        updated.revisions.len(),
        1,
        "benchmarking must not auto-promote or create workflow revisions"
    );
}

#[test]
fn improve_promote_event_policy_requires_valid_benchmark_and_records_governed_revision() {
    use forge_core::graph::{self, ExecutorKind, TaskStatus};
    use forge_core::intent;

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(intent::parse_intent(
        "Promote an event policy only after benchmark evidence",
    ));
    workflow.tasks = vec![graph::task(
        "task-policy",
        "Render repeatable partner report",
        &[],
        &[],
        vec![],
        "same partner report output",
        (ExecutorKind::Ai, 2.0),
    )];
    workflow.tasks[0].status = TaskStatus::Completed;
    workflow.tasks[0]
        .work_item
        .goal_validation
        .definitively_ready = true;
    store.save_workflow(&workflow).unwrap();
    {
        let connection = Connection::open(&store_path).unwrap();
        for index in 0..3 {
            let source_id = format!("event-policy-promote-{index}");
            let created_at = format!("2026-06-10T14:{:02}:00Z", index * 5);
            let data = serde_json::json!({
                "node_id": "task-policy",
                "addon_id": "forge.addon.reporting",
                "duration_ms": 500,
                "retry_count": 0,
                "wait_seconds": 0,
                "context": {
                    "effective_budget": 1000,
                    "routing_summary": {
                        "selected_bytes": 800 + index,
                        "remaining_budget": 200 - index
                    },
                    "memory_policy": {
                        "memory_level": "standard",
                        "memory_scope": "project"
                    }
                }
            });
            connection
                .execute(
                    r#"
                    INSERT INTO global_events (
                        source, source_id, workflow_id, kind, origin, status,
                        organization_id, brand_id, product_id, user_id, channel_id,
                        tenant_context_json, data_json, created_at
                    )
                    VALUES (
                        'event_policy_promote_seed', ?1, ?2, 'ai_executor_completed', 'codex', 'recorded',
                        'org-demo', 'brand-demo', 'product-demo', 'user-demo', 'web',
                        '{}', ?3, ?4
                    )
                    "#,
                    rusqlite::params![source_id, workflow.id, data.to_string(), created_at],
                )
                .unwrap();
        }
    }

    forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "apply-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--apply",
            "--approved-by",
            "codex-test",
            "--output",
            "json",
        ])
        .assert()
        .success();

    forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "benchmark-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success();

    forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "promote-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .stderr(predicates::str::contains("requires --approved-by"));

    let promotion_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "promote-event-policy",
            "--workflow",
            &workflow.id,
            "--policy",
            "prefer_deterministic_node",
            "--approved-by",
            "arthur",
            "--origin",
            "codex",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let promotion: Value = serde_json::from_slice(&promotion_output).unwrap();
    assert_eq!(
        promotion["schema_version"],
        "forge.improve.event_policy_promotion.v1"
    );
    assert_eq!(promotion["status"], "event_policy_promotion_accepted");
    assert_eq!(promotion["workflow_id"], workflow.id);
    assert_eq!(promotion["recommended_policy"], "prefer_deterministic_node");
    assert_eq!(promotion["approved_by"], "arthur");
    assert_eq!(promotion["promoted"], true);
    assert_eq!(promotion["auto_promoted"], false);
    assert_eq!(promotion["benchmark"]["promotion_allowed"], true);
    assert_eq!(promotion["benchmark"]["validation_passed"], true);
    assert_eq!(promotion["benchmark"]["rollback_ready"], true);
    assert_eq!(promotion["application_revision"], 1);
    assert_eq!(promotion["revision"], 2);
    assert_eq!(promotion["event_kind"], "event_improvement_policy_promoted");

    let mcp_input = serde_json::json!({
        "workflow_id": workflow.id,
        "recommended_policy": "prefer_deterministic_node",
        "approved_by": "mcp-operator",
        "origin": "mcp-test"
    });
    let mcp_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "mcp",
            "call",
            "forge.improve.promote_event_policy",
            "--input",
            &mcp_input.to_string(),
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_json: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(
        mcp_json["result"]["schema_version"],
        "forge.improve.event_policy_promotion.v1"
    );
    assert_eq!(
        mcp_json["result"]["status"],
        "event_policy_promotion_already_accepted"
    );
    assert_eq!(mcp_json["result"]["promoted"], false);
    assert_eq!(mcp_json["result"]["revision"], 2);

    let updated = ForgeStore::open(&store_path)
        .unwrap()
        .load_workflow(&workflow.id)
        .unwrap();
    assert_eq!(updated.revisions.len(), 2);
    assert_eq!(
        updated.revisions[1].change_type,
        "event_improvement_policy_promoted"
    );
    let events = ForgeStore::open(&store_path)
        .unwrap()
        .load_workflow_events(&workflow.id)
        .unwrap();
    assert_eq!(
        events
            .iter()
            .filter(|event| event.kind == "event_improvement_policy_promoted")
            .count(),
        1,
        "repeated promotion must be idempotent for the same benchmark"
    );
}

#[test]
fn improve_candidates_rank_live_workflows_with_logs_and_parallel_opportunities() {
    use chrono::{Duration, Utc};
    use forge_core::graph::{self, ExecutorKind};
    use forge_core::request::{create_run_record, save_run_record};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(forge_core::intent::parse_intent(
        "Deliver a partner demo with independent backend and frontend tracks",
    ));
    workflow.status = "running".to_string();
    workflow.tasks = vec![
        graph::task(
            "task-api",
            "Calculate daily cost report",
            &[],
            &[],
            vec![],
            "deterministic cost JSON",
            (ExecutorKind::Ai, 2.0),
        ),
        graph::task(
            "task-ui",
            "Calculate weekly cost report",
            &[],
            &[],
            vec![],
            "deterministic cost JSON",
            (ExecutorKind::Ai, 2.0),
        ),
        graph::task(
            "task-demo",
            "Assemble partner demo",
            &["task-api", "task-ui"],
            &[],
            vec![],
            "partner-ready demo package",
            (ExecutorKind::Ai, 1.0),
        ),
    ];
    store.save_workflow(&workflow).unwrap();

    let mut run = create_run_record(&workflow, "codex", "running");
    run.active_executor = Some("codex".to_string());
    run.progress_summary = Some("executor has not refreshed logs".to_string());
    run.last_heartbeat_at = Some(Utc::now() - Duration::seconds(120));
    run.heartbeat_expires_at = Some(Utc::now() - Duration::seconds(60));
    run.heartbeat_ttl_seconds = Some(30);
    save_run_record(&store, &run).unwrap();
    store
        .record_event(
            &workflow.id,
            "executor_response_promoted",
            &serde_json::json!({
                "run_id": run.run_id,
                "task_id": "task-api",
                "response_status": "needs_retry",
                "summary": "cost report output needs retry",
                "cost": {
                    "estimated_usd": 0.42,
                    "tokens_in": 1400,
                    "tokens_out": 220
                }
            }),
        )
        .unwrap();
    drop(store);

    let output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(
        report["schema_version"],
        "forge.orchestrator_improvement_candidates.v1"
    );
    let candidates = report["candidates"].as_array().unwrap();
    assert!(!candidates.is_empty());
    let top = &candidates[0];
    assert_eq!(top["workflow_id"], workflow.id);
    assert!(top["score"].as_i64().unwrap() >= 100);
    assert_eq!(
        top["parallelization"]["ready_parallel_task_count"]
            .as_u64()
            .unwrap(),
        2
    );
    assert!(top["reasons"].as_array().unwrap().iter().any(|reason| {
        reason["code"] == "stale_running_run" && reason["severity"] == "critical"
    }));
    assert!(top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| { reason["code"] == "parallelization_opportunity" }));
    assert_eq!(
        top["cost_efficiency"]["repetitive_or_deterministic_ai_task_count"],
        2
    );
    assert_eq!(
        top["cost_efficiency"]["estimated_ai_cost_average_usd"],
        5.0 / 3.0
    );
    assert_eq!(top["cost_efficiency"]["avoidable_estimated_cost_usd"], 4.0);
    assert_eq!(
        top["cost_efficiency"]["avoidable_estimated_cost_average_usd"],
        2.0
    );
    assert_eq!(top["cost_efficiency"]["observed_ai_cost_average_usd"], 0.42);
    assert_eq!(
        top["cost_efficiency"]["avoidable_observed_cost_average_usd"],
        0.42
    );
    assert_eq!(
        top["cost_efficiency"]["repetitive_or_deterministic_ai_cost_item_count"],
        1
    );
    let cost_item = &top["cost_efficiency"]["repetitive_or_deterministic_ai_cost_items"][0];
    assert_eq!(
        cost_item["item_key"],
        "calculate cost report -> deterministic cost json"
    );
    assert_eq!(cost_item["classification"], "repetitive_ai_item");
    assert_eq!(cost_item["estimated_execution_count"], 2);
    assert_eq!(cost_item["observed_execution_count"], 1);
    assert_eq!(cost_item["task_count"], 2);
    assert_eq!(
        cost_item["task_ids"],
        serde_json::json!(["task-api", "task-ui"])
    );
    assert_eq!(cost_item["estimated_cost_average_per_execution_usd"], 2.0);
    assert_eq!(
        cost_item["avoidable_estimated_cost_average_per_execution_usd"],
        2.0
    );
    assert_eq!(
        cost_item["replacement_estimated_cost_average_per_execution_usd"],
        0.0005
    );
    assert_eq!(cost_item["observed_cost_average_per_execution_usd"], 0.42);
    assert!(
        (cost_item["estimated_savings_after_replacement_total_usd"]
            .as_f64()
            .unwrap()
            - 3.999)
            .abs()
            < 1e-12
    );
    assert!(top["reasons"]
        .as_array()
        .unwrap()
        .iter()
        .any(|reason| { reason["code"] == "avoidable_ai_cost" }));

    let mcp_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "mcp",
            "call",
            "forge.improve.candidates",
            "--input",
            r#"{"limit":1}"#,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_report: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_report["status"], "ok");
    assert_eq!(
        mcp_report["result"]["schema_version"],
        "forge.orchestrator_improvement_candidates.v1"
    );
    assert_eq!(
        mcp_report["result"]["candidates"][0]["workflow_id"],
        workflow.id
    );
}

#[test]
fn improve_candidates_can_focus_scan_by_goal_text_for_active_work() {
    use forge_core::graph::{self, ExecutorKind};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();

    let mut forge_workflow = graph::create_workflow(forge_core::intent::parse_intent(
        "Improve Forge Core autonomously until the user-facing runtime result is verified.",
    ));
    forge_workflow.status = "running".to_string();
    forge_workflow.intent.deliverables = vec!["Forge Core runtime verification report".to_string()];
    forge_workflow.tasks = vec![graph::task(
        "task-forge-report",
        "Produce Forge Core runtime verification report",
        &[],
        &[],
        vec![],
        "Forge Core runtime verification report",
        (ExecutorKind::Command, 0.0002),
    )];
    store.save_workflow(&forge_workflow).unwrap();

    let mut hackathon_workflow = graph::create_workflow(forge_core::intent::parse_intent(
        "Create a hackathon pitch report with final outcome evidence.",
    ));
    hackathon_workflow.status = "running".to_string();
    hackathon_workflow.intent.deliverables = vec!["Hackathon pitch report".to_string()];
    hackathon_workflow.tasks = vec![graph::task(
        "task-hackathon-report",
        "Produce hackathon pitch report",
        &[],
        &[],
        vec![],
        "Hackathon pitch report",
        (ExecutorKind::Command, 0.0002),
    )];
    store.save_workflow(&hackathon_workflow).unwrap();
    drop(store);

    let output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "improve",
            "candidates",
            "--goal-contains",
            "Forge Core",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let report: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(report["total_workflows"], 2);
    assert_eq!(report["matched_workflows"], 1);
    assert_eq!(
        report["filter"]["goal_contains"],
        serde_json::json!(["Forge Core"])
    );
    let candidates = report["candidates"].as_array().unwrap();
    assert_eq!(candidates.len(), 1);
    assert_eq!(candidates[0]["workflow_id"], forge_workflow.id);
    assert_ne!(candidates[0]["workflow_id"], hackathon_workflow.id);

    let mcp_output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "mcp",
            "call",
            "forge.improve.candidates",
            "--input",
            r#"{"limit":5,"goal_contains":["Forge Core"]}"#,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let mcp_report: Value = serde_json::from_slice(&mcp_output).unwrap();
    assert_eq!(mcp_report["status"], "ok");
    assert_eq!(mcp_report["result"]["matched_workflows"], 1);
    assert_eq!(
        mcp_report["result"]["candidates"][0]["workflow_id"],
        forge_workflow.id
    );
}

