#[test]
fn request_drive_surfaces_all_ready_parallel_handoffs() {
    use forge_core::graph::{self, ExecutorKind};
    use forge_core::request::{create_run_record, save_run_record};

    let temp = tempdir().unwrap();
    let store_path = temp.path().join("forge.sqlite");
    let store = ForgeStore::open(&store_path).unwrap();
    let mut workflow = graph::create_workflow(forge_core::intent::parse_intent(
        "Ship independent implementation tracks then merge the result",
    ));
    workflow.status = "running".to_string();
    workflow.tasks = vec![
        graph::task(
            "task-api",
            "Build API track",
            &[],
            &[],
            vec![],
            "API artifact",
            (ExecutorKind::Ai, 1.0),
        ),
        graph::task(
            "task-ui",
            "Build UI track",
            &[],
            &[],
            vec![],
            "UI artifact",
            (ExecutorKind::Ai, 1.0),
        ),
        graph::task(
            "task-merge",
            "Merge tracks",
            &["task-api", "task-ui"],
            &[],
            vec![],
            "merged result",
            (ExecutorKind::Ai, 1.0),
        ),
    ];
    store.save_workflow(&workflow).unwrap();
    let run = create_run_record(&workflow, "codex", "running");
    save_run_record(&store, &run).unwrap();
    drop(store);

    let output = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "request",
            "drive",
            "--run",
            &run.run_id,
            "--executor",
            "codex",
            "--ttl-seconds",
            "300",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let drive: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(drive["status"], "ready_for_handoff");
    assert_eq!(drive["action"], "start_parallel_handoffs");
    assert_eq!(drive["parallel_handoff_tasks"].as_array().unwrap().len(), 2);
    assert_eq!(drive["parallel_next_commands"].as_array().unwrap().len(), 2);
    assert!(drive["reason"].as_str().unwrap().contains("parallel"));

    let completed_second = forge()
        .args([
            "--store",
            store_path.to_str().unwrap(),
            "request",
            "complete-task",
            "--run",
            &run.run_id,
            "--task",
            "task-ui",
            "--executor",
            "codex",
            "--summary",
            "UI track finished by a parallel executor.",
            "--evidence-command",
            "true",
            "--evidence-summary",
            "parallel task evidence passed",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let completed_second_json: Value = serde_json::from_slice(&completed_second).unwrap();
    assert_eq!(completed_second_json["status"], "completed");
    assert_eq!(completed_second_json["task_id"], "task-ui");
}

#[test]
fn planned_tasks_include_scrum_safe_style_operational_metadata() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Evolve Forge task structure with backlog, impediments, subtasks and process governance",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let first_task = &json["tasks"].as_array().unwrap()[0];
    assert!(first_task["goal"]
        .as_str()
        .unwrap()
        .contains("Parse intent"));
    assert_eq!(first_task["work_item"]["backlog_state"], "ready");
    assert_eq!(first_task["work_item"]["priority"], "p1");
    let subtasks = first_task["work_item"]["subtasks"].as_array().unwrap();
    assert!(!subtasks.is_empty());
    assert!(subtasks.iter().all(|subtask| subtask["goal"].is_string()));
    assert!(subtasks
        .iter()
        .all(|subtask| subtask["definition_of_done"].is_array()));
    assert!(first_task["work_item"]["impediments"].is_array());
    assert!(first_task["work_item"]["goal_validation"]["definitively_ready"].is_boolean());
    assert!(first_task["work_item"]["acceptance_criteria"]
        .as_array()
        .unwrap()
        .iter()
        .any(|criterion| criterion.as_str().unwrap().contains("Validation rules")));
}

#[test]
fn validation_blocks_goal_oriented_tasks_until_goals_are_definitively_done() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Build a goal-oriented runtime that reworks unfinished tasks",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();

    let validation_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "validate",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .failure()
        .get_output()
        .stdout
        .clone();
    let validation: Value = serde_json::from_slice(&validation_output).unwrap();
    assert!(validation["failed_rules"]
        .as_array()
        .unwrap()
        .iter()
        .any(|rule| rule["kind"] == "goal_readiness"));
    assert!(validation["rework_tasks"]
        .as_array()
        .unwrap()
        .iter()
        .any(|task| task["reason"]
            .as_str()
            .unwrap()
            .contains("not definitively ready")));

    forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "run",
            "--workflow",
            workflow_id,
            "--simulate",
            "--output",
            "json",
        ])
        .assert()
        .success();

    let passed = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "validate",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let passed_json: Value = serde_json::from_slice(&passed).unwrap();
    assert!(passed_json["rework_tasks"].as_array().unwrap().is_empty());
}

#[test]
fn artifacts_command_lists_persistent_outputs_for_workflow() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "plan",
            "--goal",
            "Create reusable operational memory artifacts",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let json: Value = serde_json::from_slice(&output).unwrap();
    let workflow_id = json["workflow_id"].as_str().unwrap();

    forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "improve",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success();

    let artifacts_output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "artifacts",
            "--workflow",
            workflow_id,
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let artifacts: Value = serde_json::from_slice(&artifacts_output).unwrap();
    assert_eq!(artifacts["workflow_id"], workflow_id);
    assert_eq!(artifacts["artifacts"].as_array().unwrap().len(), 2);
    assert!(
        artifacts["artifacts"][0]["path"]
            .as_str()
            .unwrap()
            .contains("changelog-")
            || artifacts["artifacts"][0]["path"]
                .as_str()
                .unwrap()
                .contains("improvement-")
    );
    assert!(artifacts["artifacts"][0]["sha256"].as_str().unwrap().len() >= 64);
    assert!(artifacts["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .any(|artifact| artifact["path"].as_str().unwrap().contains("changelog-")));
    assert!(artifacts["artifacts"]
        .as_array()
        .unwrap()
        .iter()
        .any(|artifact| artifact["path"].as_str().unwrap().contains("improvement-")));
}

