#[test]
fn self_run_falls_back_to_gemini_before_codex_if_previous_executor_fails() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    let status = std::process::Command::new("git")
        .arg("init")
        .arg(&repo)
        .status()
        .expect("git init should succeed");
    assert!(status.success());
    fs::write(repo.join("README.md"), "# repo\n").unwrap();

    let executors_dir = temp.path().join("bin");
    fs::create_dir_all(&executors_dir).unwrap();

    write_fake_executor(&executors_dir, "opencode", "#!/bin/sh\nexit 1\n");
    write_fake_executor(
        &executors_dir,
        "gemini",
        "#!/bin/sh\nprintf 'ok from gemini'\nexit 0\n",
    );
    write_fake_executor(&executors_dir, "codex", "#!/bin/sh\nexit 0\n");

    let old_path = std::env::var("PATH").unwrap_or_else(|_| "".to_string());
    let path = format!("{}:{}", executors_dir.display(), old_path);

    let output = forge()
        .env("PATH", path)
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--validation-command",
            "true",
            "--skip-self-update",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let cycle_report = &json["cycle_reports"][0];
    assert_eq!(cycle_report["requested_executor"], "opencode");
    assert_eq!(cycle_report["executor"], "gemini");
    assert_eq!(
        cycle_report["executor_fallbacks"],
        serde_json::json!(["gemini", "codex"])
    );
    let attempts = cycle_report["executor_attempts"].as_array().unwrap();
    assert_eq!(attempts.len(), 2);
    assert_eq!(attempts[0]["executor"], "opencode");
    assert_eq!(attempts[0]["status"], "failed");
    assert_eq!(attempts[0]["local"], false);
    assert_eq!(attempts[0]["provider"], "google");
    assert_eq!(attempts[0]["model"], "google/gemini-2.5-pro");
    assert!(attempts[0]["next_fallback_reason"]
        .as_str()
        .unwrap()
        .contains("selected as first quota-aware candidate"));
    assert_eq!(attempts[1]["executor"], "gemini");
    assert_eq!(attempts[1]["status"], "completed");
    assert_eq!(attempts[1]["provider"], "google");
    assert_eq!(attempts[1]["model"], "gemini-2.5-pro");
    assert!(attempts[1]["next_fallback_reason"]
        .as_str()
        .unwrap()
        .contains("selected after an earlier quota-aware executor attempt failed"));
}

#[test]
fn self_run_reports_quota_aware_executor_policy_for_cycle() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    fs::write(repo.join("README.md"), "# Repo\n").unwrap();

    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--executor",
            "opencode",
            "--fallback-executor",
            "gemini",
            "--fallback-executor",
            "codex",
            "--dry-run",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let policy = &json["cycle_reports"][0]["executor_policy"];
    assert_eq!(
        policy["schema_version"],
        "forge.self_evolution.executor_policy.v1"
    );
    assert_eq!(
        policy["selection_principle"],
        "maximize useful progress under expected value, quota, cost, latency, quality and fallback risk constraints"
    );
    assert_eq!(
        policy["quota_decision_summary"],
        "spend_non_local_quota_for_high_value_self_evolution"
    );
    assert_eq!(
        policy["requested_chain"],
        serde_json::json!(["opencode", "gemini", "codex"])
    );
    assert_eq!(
        policy["selected_candidate"],
        serde_json::json!({
            "executor": "opencode",
            "provider": "google",
            "model": "google/gemini-2.5-pro",
            "local_vs_non_local": "non_local",
            "selection_tier": 10,
            "selection_status": "eligible",
            "reason": "selected as first quota-aware candidate that is not blocked by prior timeout or configuration evidence",
            "business_value_justification": "Selected candidate has business_value_score=80 and suitability='high_for_high_value_pm_business_or_creative_reasoning'. Progressing with highest value eligible non-local option."
        })
    );
    assert_eq!(
        policy["fallback_order"],
        serde_json::json!([
            {
                "executor": "opencode",
                "provider": "google",
                "model": "google/gemini-2.5-pro",
                "local_vs_non_local": "non_local",
                "selection_tier": 10,
                "selection_status": "eligible"
            },
            {
                "executor": "gemini",
                "provider": "google",
                "model": "gemini-2.5-pro",
                "local_vs_non_local": "non_local",
                "selection_tier": 21,
                "selection_status": "eligible"
            },
            {
                "executor": "codex",
                "provider": "openai",
                "model": null,
                "local_vs_non_local": "non_local",
                "selection_tier": 32,
                "selection_status": "eligible"
            },
            {
                "executor": "opencode",
                "provider": "configured_cli",
                "model": null,
                "local_vs_non_local": "non_local",
                "selection_tier": 35,
                "selection_status": "eligible"
            },
            {
                "executor": "opencode",
                "provider": "ollama",
                "model": "ollama/qwen3:14b",
                "local_vs_non_local": "local",
                "selection_tier": 40,
                "selection_status": "eligible"
            }
        ])
    );
    let candidates = policy["candidates"].as_array().unwrap();
    let selection_trace = policy["selection_trace"]
        .as_array()
        .expect("self-evolution executor policy should expose a selection trace");
    assert_eq!(
        selection_trace[0]["schema_version"],
        "forge.executor_selection_trace.v1"
    );
    assert_eq!(selection_trace[0]["executor"], "opencode");
    assert_eq!(selection_trace[0]["provider"], "google");
    assert_eq!(selection_trace[0]["decision"], "select");
    assert_eq!(selection_trace[0]["selection_status"], "eligible");
    assert!(selection_trace[0]["next_fallback_reason"]
        .as_str()
        .unwrap()
        .contains("selected as first quota-aware candidate"));
    let ordered: Vec<_> = candidates
        .iter()
        .map(|candidate| {
            (
                candidate["executor"].as_str().unwrap(),
                candidate["provider"].as_str().unwrap(),
                candidate["local_vs_non_local"].as_str().unwrap(),
            )
        })
        .collect();
    assert_eq!(
        ordered,
        vec![
            ("opencode", "google", "non_local"),
            ("gemini", "google", "non_local"),
            ("codex", "openai", "non_local"),
            ("opencode", "configured_cli", "non_local"),
            ("opencode", "ollama", "local"),
        ]
    );
    assert!(candidates.iter().any(|candidate| {
        candidate["executor"] == "gemini"
            && candidate["local_vs_non_local"] == "non_local"
            && candidate["quota_model"] == "quota_bound"
            && candidate["non_interactive_requirement"]
                .as_str()
                .unwrap()
                .contains("must not wait for approval")
    }));
    assert!(candidates.iter().any(|candidate| {
        candidate["executor"] == "codex"
            && candidate["local_vs_non_local"] == "non_local"
            && candidate["free_vs_paid_if_known"] == "not_free_quota_bound"
    }));
    assert!(candidates.iter().any(|candidate| {
        candidate["executor"] == "opencode"
            && candidate["provider"] == "ollama"
            && candidate["local_vs_non_local"] == "local"
            && candidate["selection_tier"].as_u64().unwrap() > 3
    }));
    assert!(policy["repair_goals"]
        .as_array()
        .unwrap()
        .iter()
        .any(|goal| goal.as_str().unwrap().contains("Gemini non-interactive")));
}

#[test]
fn self_run_keeps_codex_non_local_ahead_of_opencode_paid_and_local_when_gemini_is_requested() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let repo = temp.path().join("repo");
    fs::create_dir_all(&repo).unwrap();
    fs::write(repo.join("README.md"), "# Repo\n").unwrap();

    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "self",
            "run",
            "--repo",
            repo.to_str().unwrap(),
            "--until",
            "2999-01-01T00:00:00-03:00",
            "--max-cycles",
            "1",
            "--executor",
            "gemini",
            "--fallback-executor",
            "codex",
            "--fallback-executor",
            "opencode",
            "--dry-run",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    let policy = &json["cycle_reports"][0]["executor_policy"];
    assert_eq!(
        policy["requested_chain"],
        serde_json::json!(["gemini", "codex", "opencode"])
    );

    let candidates = policy["candidates"].as_array().unwrap();
    let codex_index = candidates
        .iter()
        .position(|candidate| candidate["executor"] == "codex")
        .unwrap();
    let opencode_paid_index = candidates
        .iter()
        .position(|candidate| {
            candidate["executor"] == "opencode"
                && candidate["provider"] == "configured_cli"
                && candidate["local_vs_non_local"] == "non_local"
        })
        .unwrap();
    let opencode_local_index = candidates
        .iter()
        .position(|candidate| {
            candidate["executor"] == "opencode"
                && candidate["provider"] == "ollama"
                && candidate["local_vs_non_local"] == "local"
        })
        .unwrap();

    assert!(
        codex_index < opencode_paid_index,
        "Codex non-local should be tried before OpenCode paid/unknown fallback"
    );
    assert!(
        codex_index < opencode_local_index,
        "Codex non-local should be tried before OpenCode local/Ollama fallback"
    );
    assert!(
        candidates[opencode_local_index]["selection_tier"]
            .as_u64()
            .unwrap()
            > candidates[codex_index]["selection_tier"].as_u64().unwrap()
    );
}

