#[test]
fn no_args_tty_enters_repl_and_shows_dashboard_when_pseudo_terminal_is_available() {
    let script = if Path::new("/usr/bin/script").exists() {
        "/usr/bin/script"
    } else if Path::new("/bin/script").exists() {
        "/bin/script"
    } else {
        return;
    };
    let timeout = if Path::new("/usr/bin/timeout").exists() {
        "/usr/bin/timeout"
    } else if Path::new("/bin/timeout").exists() {
        "/bin/timeout"
    } else {
        return;
    };
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");
    let binary = assert_cmd::cargo::cargo_bin("forge");
    let command = format!("{} --store {}", binary.display(), store.display());

    let output = std::process::Command::new(timeout)
        .args(["2", script, "-q", "-c", &command, "/dev/null"])
        .output()
        .unwrap();

    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("forge"));
    assert!(stdout.contains("Active runs"));
    assert!(stdout.contains("Quick actions"));
    assert!(stdout.contains("/status"));
}

#[test]
fn interactive_slash_command_catalog_is_discoverable_and_scriptable() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");

    let output = forge()
        .args([
            "--store",
            store.to_str().unwrap(),
            "interactive",
            "slash-commands",
            "--output",
            "json",
        ])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();

    let json: Value = serde_json::from_slice(&output).unwrap();
    assert_eq!(json["status"], "slash_commands_loaded");
    assert_eq!(
        json["schema_version"],
        "forge.interactive.slash_commands.v1"
    );
    for name in [
        "/help",
        "/status",
        "/list",
        "/inspect",
        "/runs",
        "/workflows",
        "/artifacts",
        "/task-board",
        "/costs",
        "/config",
        "/sync",
        "/executors",
        "/brains",
        "/shells",
        "/harness",
        "/runtimes",
        "/validate",
        "/approve",
        "/reject",
        "/goal",
        "/attach",
        "/resume",
        "/pause",
        "/stop",
        "/delete",
        "/export",
        "/logs",
        "/update",
        "/workers",
        "/context",
        "/handoff",
        "/pm",
        "/decision",
        "/exit",
        "/quit",
    ] {
        let command = find_slash_command(&json, name);
        assert_eq!(command["name"], name);
        assert_eq!(command["scriptable"], true);
        if name == "/exit" || name == "/quit" {
            assert!(
                command["equivalent_command"].as_array().unwrap().is_empty(),
                "/exit and /quit are REPL-only and should have no equivalent forge command"
            );
        } else {
            assert!(
                command["equivalent_command"].as_array().unwrap().len() >= 2,
                "{name} should have at least 2 equivalent commands"
            );
        }
    }

    let status = find_slash_command(&json, "/status");
    assert_eq!(status["risk_level"], "low");
    assert_eq!(status["mutates_workflow"], false);
    assert!(status["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("status".to_string())));

    let context = find_slash_command(&json, "/context");
    assert_eq!(context["risk_level"], "low");
    assert_eq!(context["mutates_workflow"], false);
    assert!(context["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("context".to_string())));

    let handoff = find_slash_command(&json, "/handoff");
    assert_eq!(handoff["risk_level"], "medium");
    assert_eq!(handoff["mutates_workflow"], true);
    assert!(handoff["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("handoff".to_string())));

    let pm = find_slash_command(&json, "/pm");
    assert_eq!(pm["risk_level"], "medium");
    assert_eq!(pm["mutates_workflow"], true);
    assert!(pm["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("interactive".to_string())));

    let decision = find_slash_command(&json, "/decision");
    assert_eq!(decision["risk_level"], "medium");
    assert_eq!(decision["mutates_workflow"], true);
    assert!(decision["equivalent_command"]
        .as_array()
        .unwrap()
        .contains(&Value::String("decision".to_string())));
}

