#[test]
fn mcp_exposes_interactive_cli_home_slash_and_route_for_agents() {
    let temp = tempdir().unwrap();
    let store = temp.path().join("forge.sqlite");

    let manifest = forge()
        .args(["mcp", "tools", "--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let manifest_json: Value = serde_json::from_slice(&manifest).unwrap();

    for (name, output_schema, mutates_workflow) in [
        ("forge.interactive.home", "forge.interactive.home.v1", false),
        ("forge.brain_router", "forge.brain_router.v1", false),
        (
            "forge.interactive.slash_commands",
            "forge.interactive.slash_commands.v1",
            false,
        ),
        (
            "forge.interactive.route",
            "forge.interactive.route.v1",
            true,
        ),
    ] {
        let tool = find_mcp_tool(&manifest_json, name);
        assert_eq!(tool["output_schema"], output_schema);
        assert_eq!(tool["async_safe"], true);
        assert_eq!(tool["mutates_workflow"], mutates_workflow);
    }

    let home = forge()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .current_dir(temp.path())
        .args(["mcp", "call", "forge.interactive.home"])
        .args(["--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let home_json: Value = serde_json::from_slice(&home).unwrap();
    assert_eq!(home_json["status"], "ok");
    assert_eq!(
        home_json["result"]["schema_version"],
        "forge.interactive.home.v1"
    );
    assert!(home_json["result"]["dashboard"]["quick_actions"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("/status")));
    assert!(home_json["result"]["dashboard"]["quick_actions"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("/brains")));
    assert!(home_json["result"]["dashboard"]["quick_actions"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("/harness")));
    assert!(home_json["result"]["dashboard"]["workflow_focus"].is_array());
    assert_eq!(
        home_json["result"]["dashboard"]["harness_mode_panel"]["schema_version"],
        "forge.harness.mode.v1"
    );
    assert!(
        home_json["result"]["dashboard"]["harness_mode_panel"]["effective_mode"].is_string(),
        "interactive home should expose harness mode for shell and brain dashboards"
    );
    assert!(
        home_json["result"]["dashboard"]["task_board_panel"]["schema_version"]
            == "forge.interactive.task_board.v1",
        "interactive home should expose task-board state for agent dashboards"
    );
    assert!(
        home_json["result"]["dashboard"]["schedule_panel"]["status"].is_string(),
        "interactive home should expose scheduler panel state for agent dashboards"
    );
    assert!(
        home_json["result"]["dashboard"]["event_panel"]["status"].is_string(),
        "interactive home should expose global event timeline state for agent dashboards"
    );
    assert!(
        home_json["result"]["dashboard"]["cost_panel"]["status"].is_string(),
        "interactive home should expose cost ledger state for agent dashboards"
    );
    assert!(
        home_json["result"]["dashboard"]["context_memory_panel"]["memory_policy_status"]
            .is_string(),
        "interactive home should expose context and memory policy state for agent dashboards"
    );

    let brain_router = forge()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args(["mcp", "call", "forge.brain_router"])
        .args(["--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let brain_router_json: Value = serde_json::from_slice(&brain_router).unwrap();
    assert_eq!(
        brain_router_json["result"]["schema_version"],
        "forge.brain_router.v1"
    );
    assert_eq!(brain_router_json["result"]["controller"], "forge");
    assert!(brain_router_json["result"]["forge_controlled_surfaces"]
        .as_array()
        .unwrap()
        .contains(&serde_json::json!("mcp_servers_and_tools")));

    let slash = forge()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args(["mcp", "call", "forge.interactive.slash_commands"])
        .args(["--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let slash_json: Value = serde_json::from_slice(&slash).unwrap();
    assert_eq!(
        slash_json["result"]["schema_version"],
        "forge.interactive.slash_commands.v1"
    );
    assert!(slash_json["result"]["commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command["name"] == "/patch apply" && command["mutates_workflow"] == true));
    assert!(slash_json["result"]["commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command["name"] == "/patch review" && command["mutates_workflow"] == false));
    assert!(slash_json["result"]["commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command["name"] == "/patch diff" && command["mutates_workflow"] == false));
    assert!(slash_json["result"]["commands"]
        .as_array()
        .unwrap()
        .iter()
        .any(|command| command["name"] == "/patch restore" && command["mutates_workflow"] == true));

    let route_input = serde_json::json!({
        "input": "What is the current Forge status?",
        "origin": "mcp_test"
    })
    .to_string();
    let routed = forge()
        .arg("--store")
        .arg(store.to_str().unwrap())
        .args(["mcp", "call", "forge.interactive.route"])
        .arg("--input")
        .arg(&route_input)
        .args(["--output", "json"])
        .assert()
        .success()
        .get_output()
        .stdout
        .clone();
    let routed_json: Value = serde_json::from_slice(&routed).unwrap();
    assert_eq!(
        routed_json["result"]["schema_version"],
        "forge.interactive.route.v1"
    );
    assert_eq!(routed_json["result"]["routing_decision"], "direct_answer");
    assert_eq!(routed_json["result"]["workflow_created"], false);
}

